import{_ as a,o as t,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Media Package & Campaign - V2 implementation baseline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/README.md","filePath":"feature/media-package-campaign/README.md"}'),n={name:"feature/media-package-campaign/README.md"};function r(s,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="media-package-campaign-v2-implementation-baseline" tabindex="-1">Media Package &amp; Campaign - V2 implementation baseline <a class="header-anchor" href="#media-package-campaign-v2-implementation-baseline" aria-label="Permalink to &quot;Media Package &amp; Campaign - V2 implementation baseline&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p><strong>Checkpoint mới — 2026-10-13:</strong> phần 3.5 còn lại bắt đầu bằng giai đoạn 1 tài liệu, khác với phase-1-design của đợt Campaign cũ. Xem <a href="./remaining-work/spec.html">spec đã chốt</a>, <a href="./remaining-work/plan.html">kế hoạch 5 giai đoạn</a>, <a href="./remaining-work/task.html">checklist</a> và <a href="./remaining-work/test.html">test matrix</a>. Thứ tự mới: DA-951 → DA-949/950 → history/regression. Chỉ tạo Request khi Campaign IN_PROGRESS và deployment SUCCEEDED; Request cũ tiếp tục xử lý sau hoàn thành. Owner-only danh bạ, inactive giữ liên kết cũ; không scheduled reminder.</p><p>Class diagram cho FR 3.5.1–3.5.10: <a href="./class-diagram.html">Mô hình lớp Package, Campaign và Content Request</a>.</p><p><strong>Điểm bắt đầu khi tiếp tục công việc:</strong> <a href="./implementation-roadmap.html">Lộ trình 6 giai đoạn</a> ghi trạng thái, thứ tự triển khai, Jira, tiêu chí bàn giao và các quyết định còn mở.</p><p>Giai đoạn 1 đã hoàn thành thiết kế: <a href="./phase-1-design/spec.html">spec/plan/task/test</a>. Đã chốt tổng sản lượng cả gói, Task EVENT_PLAN/PRESS_RECOMMENDATION và Manager complete với lý do khi còn Task dang dở. Giai đoạn 2–5 đã có code; điểm tiếp theo là xác minh migration Atlas và smoke test API/browser theo roadmap.</p><p><strong>Latest BA, 2026-10-08:</strong> one Workspace has one Campaign, created from its approved package. A new campaign uses a new Workspace; Owner can duplicate selected information and resources from an existing Workspace. This supersedes multiple cooperation rounds in one Workspace. See <a href="./campaign-delivery-plan.html">Campaign delivery plan</a> for rollout, copy scope and remaining verification. Campaign draft, review/deployment and selective Workspace duplication are implemented in code; this does not imply Jira Done.</p><p>October 2026 structured offering extension: see <a href="./offering-models/spec.html">offering-models/spec.md</a> and its plan/task/test. This slice adds packaging, deliverables, immutable negotiation snapshots and draft Campaign allocation only; E50-08/09 and detailed E51 service implementations remain separate.</p><p>This folder is the technical working baseline for FR 3.5.1--3.5.10. It is intended to make the first implementation slice unambiguous; it is not a replacement for BA documents.</p><h2 id="source-of-truth-and-conflicts" tabindex="-1">Source of truth and conflicts <a class="header-anchor" href="#source-of-truth-and-conflicts" aria-label="Permalink to &quot;Source of truth and conflicts&quot;">​</a></h2><ol><li>Business flow: <code>docs/ba/04-media-package-campaign.md</code>, <code>05-content-task-workflow.md</code>, and <code>12-state-machines.md</code>.</li><li>V2 data-model decision: <code>docs/database/database-strategy.md</code>, section 4.3.</li><li>Delivery decomposition: <code>docs/plan/brandhub-master-plan.md</code>, E50 and E51.</li></ol><p><code>11-data-entities-glossary.md</code> still describes a two-table, <code>packageRefType</code> model. It is superseded for implementation by the V2 decision: one PostgreSQL <code>media_packages</code> table distinguished by <code>is_template</code>. A workspace package references it through the single <code>workspace_media_packages.package_id</code> foreign key.</p><h2 id="confirmed-v2-baseline" tabindex="-1">Confirmed V2 baseline <a class="header-anchor" href="#confirmed-v2-baseline" aria-label="Permalink to &quot;Confirmed V2 baseline&quot;">​</a></h2><ul><li>An Admin template has <code>is_template = true</code> and <code>agency_id IS NULL</code>; every Agency may view this global catalogue.</li><li>Until the separate Admin implementation is delivered, global templates are supplied by seed data. Admin template authoring is not part of this feature slice.</li><li>An Agency package has <code>is_template = false</code> and a required <code>agency_id</code>. Only the Agency Owner manages this catalogue. A package can be authored independently or cloned from a global template; <code>source_template_id</code> records optional provenance without coupling later edits.</li><li>The Owner controls Agency-wide Workspace visibility with <code>is_available_to_workspaces</code>. Hiding a package removes it from future selection but does not invalidate a package already selected by a Workspace.</li><li>Workspace creation already adds the Client. The Client selects only an available package from that Workspace&#39;s Agency; global Admin templates are reference material for the Owner and cannot be selected directly. <code>workspace_media_packages</code> records the selected, negotiable package. It is replaceable before negotiation starts and fixed to the same package once negotiation begins.</li><li>Until Package approval, the Workspace dashboard redirects to selection/negotiation. Client retains Package/Chat, Manager also retains Workspace settings; creative features remain gated. No scheduled reminder is required.</li><li>Selection snapshots package terms into <code>workspace_media_packages.final_terms</code>; later edits to a global template must not retroactively change a Workspace&#39;s selected terms.</li><li>A change to terms creates a new terms version. Both approval records for the prior version are invalid and Agency and Client must approve the new version again.</li><li>A Client can cancel a pending content request using terminal status <code>CANCELLED</code>, rather than hard deletion, so its audit history remains available.</li><li>A campaign can be created only from an approved workspace package. It starts as <code>DRAFT</code>; deployment creates generic Mongo <code>tasks</code> in <code>backlog</code>.</li><li><code>content_requests</code> are independent of campaign work items; NEW requests require the Workspace Campaign IN_PROGRESS and deployment SUCCEEDED. Existing requests continue after completion. When accepted, one generic task is created with <code>campaignId: null</code>.</li><li>A Content Request includes Client-selected <code>type</code> (<code>POST</code>, <code>LIVESTREAM</code>, or <code>SURVEY</code>) and <code>dueDate</code>; acceptance maps those values to the generated task.</li><li>Campaign <code>work_items</code> are stored as JSONB. Each item has stable <code>id</code>, <code>name</code>, <code>type</code>, and <code>dueDate</code>. Tasks created from work items must be idempotent; query tasks by <code>campaignId</code> rather than duplicating task IDs in PostgreSQL.</li><li>Generated tasks record provenance: Content Request tasks use <code>sourceType=CONTENT_REQUEST</code> plus <code>sourceRefId</code>; campaign tasks use <code>campaignId</code> plus <code>campaignWorkItemId</code>. Each pair is unique for its generation source.</li></ul><h2 id="current-delivery-order" tabindex="-1">Current delivery order <a class="header-anchor" href="#current-delivery-order" aria-label="Permalink to &quot;Current delivery order&quot;">​</a></h2><ol><li>E50-01: global template and Agency catalogue persistence/APIs.</li><li>E50-02 and E50-03: workspace package selection/read model.</li><li>E50-04 and E50-05: negotiation history and two-party approval.</li><li>E50-06 and E50-07: campaign work items, approval, and idempotent deploy.</li><li>E50-10 with E51-01: content request lifecycle and generated task.</li></ol><p>E50-09 / DA-950 now has manual per-Campaign partner tracking APIs and a dedicated Workspace page for Owner/Manager/Creator/Client. See the <a href="./campaign-collaborators/spec.html">spec, plan, task and test evidence</a>. E50-08 / DA-949 now adds Owner-only Agency directory CRUD/deactivation at <code>/agency/:id/collaborators</code>; DA-950 selection is active-only and retains inactive existing links. See <a href="./partner-directory/test.html">directory evidence</a>. PostgreSQL migration <code>2026-10-13-partner-directory-lifecycle.sql</code> and matching init are prepared and tested on an isolated PostgreSQL, <strong>not applied to the shared DB</strong>. Legacy unverified history blocks deletion; no reactivate/verification API. Real JWT/Gateway smoke remains to be verified; code completion is not Jira Done.</p><h2 id="decisions-required-before-affected-code" tabindex="-1">Decisions required before affected code <a class="header-anchor" href="#decisions-required-before-affected-code" aria-label="Permalink to &quot;Decisions required before affected code&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Why it matters</th></tr></thead><tbody><tr><td>Scheduled reminder</td><td>Removed by confirmed BA 2026-10-13; preserve current gate, no scheduler.</td></tr><tr><td>Campaign addendum</td><td>Confirmed business concept after deployment, but no E50 task owns it yet.</td></tr></tbody></table><p>Do not silently choose behaviour for an open decision.</p><h2 id="remaining-work-phase-5-—-2026-10-13" tabindex="-1">Remaining-work phase 5 — 2026-10-13 <a class="header-anchor" href="#remaining-work-phase-5-—-2026-10-13" aria-label="Permalink to &quot;Remaining-work phase 5 — 2026-10-13&quot;">​</a></h2><p>DA-945 immutable negotiation history + honest legacy baseline and read-only UI diff are implemented. DA-946 now requires displayed <code>expectedTermsVersion</code> for proposal and approval; old clients must update. DRAFT switches advance version; repeat same-side approval preserves the original timestamp. History actor uses the effective Workspace membership, including an Owner acting as Manager.</p><p>New SQL: <code>2026-10-13-package-negotiation-history.sql</code> (after phase-4 partner lifecycle). Neither new SQL nor Request Atlas migrations were applied to the shared databases. Automated checks do not replace live Gateway/account acceptance. Follow <a href="./test-setup.html">test setup</a> before running the complete flow. No auto commit/push.</p><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><ul><li>Do not initialise MongoDB; shared Atlas is already provisioned.</li><li>Use an idempotent Mongo migration to normalise the existing legacy <code>content_requests</code> collection; do not rerun <code>init-mongo.js</code> against Atlas.</li><li>Admin UI for global-template authoring and billing/KPI accounting are outside this initial slice.</li></ul>',25)])])}const g=a(n,[["render",r]]);export{h as __pageData,g as default};
